import { useState } from 'react';
import { JxButton, JxDrawer, JxMenu } from '@jinx-ui/react';

interface NavMenuProps {
  onNavigate: (key: 'projects' | 'team' | 'settings' | 'logout') => void;
}

export default function NavMenu({ onNavigate }: NavMenuProps) {
  const [open, setOpen] = useState(false);

  const handleSelect = (key: 'projects' | 'team' | 'settings' | 'logout') => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <JxButton variant="ghost" onClick={() => setOpen(true)}>
        Меню
      </JxButton>
      <JxDrawer open={open} onOpenChange={setOpen} title="Навигация" side="left">
        <JxMenu
          items={[
            { label: 'Проекты', onSelect: () => handleSelect('projects') },
            { label: 'Команда', onSelect: () => handleSelect('team') },
            { label: 'Настройки', onSelect: () => handleSelect('settings') },
            { type: 'divider' },
            { label: 'Выйти', danger: true, onSelect: () => handleSelect('logout') },
          ]}
        />
      </JxDrawer>
    </>
  );
}

